    "seoTitle": "SNS Marketing Strategy: Ultimate Guide to Modern Business Growth",
    "metaDescription": "Master sns marketing with this complete guide. Discover organic growth tactics, paid advertising strategies, short-form video tips, and key metrics.",
    "keywords": "sns marketing, social media strategy, digital marketing growth, social commerce, paid social advertising",
    "draft": false,
    "imageUrl": "https://images.unsplash.com/photo-1611162617213-7d7a39e9b1d7",
    "imageAlt": "Digital strategist analyzing social media marketing growth metrics on mobile and laptop screens",
    "createdAtSeconds": 1785279342
